import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.DCluYYrN.js";const p=JSON.parse('{"title":"Interface","description":"The five skins, thirteen navbar styles and customization center of the FoxSu manager.","frontmatter":{"title":"Interface","description":"The five skins, thirteen navbar styles and customization center of the FoxSu manager.","outline":"deep"},"headers":[],"relativePath":"features.md","filePath":"features.md"}'),i={name:"features.md"};function n(l,e,s,d,c,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="interface" tabindex="-1">Interface <a class="header-anchor" href="#interface" aria-label="Permalink to &quot;Interface&quot;">​</a></h1><p>FoxSu keeps the KernelSU kernel and rewrites the manager. This page is about the latter — the part you actually look at and touch.</p><blockquote><p>Root in the kernel, experience in the manager.</p></blockquote><h2 id="five-skins" tabindex="-1">Five skins <a class="header-anchor" href="#five-skins" aria-label="Permalink to &quot;Five skins&quot;">​</a></h2><p>Switch under Settings → Appearance. The change is global: home, modules, logs and settings all re-typeset at once. It is not a wallpaper swap.</p><table tabindex="0"><thead><tr><th>Skin</th><th>Layout language</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Redesign</strong> (Miuix)</td><td>Glass cards + capsule navbar</td><td>Default. Densest layout: one hero card plus four KPI cards</td></tr><tr><td><strong>Editorial</strong></td><td>Magazine</td><td>Paper tone, rule lines, serif headings, native bottom bar</td></tr><tr><td><strong>Pages</strong> (Fresh)</td><td>Generous whitespace</td><td>Large titles and sectioned lists, good for one-handed use</td></tr><tr><td><strong>Glass</strong></td><td>Liquid glass</td><td>Translucent cards with soft highlights, best over a wallpaper</td></tr><tr><td><strong>Nocturne</strong></td><td>Dark neon</td><td>Dark-first with neon outlines and glowing accents</td></tr></tbody></table><p>All five share the same features and settings, so switching never loses your configuration.</p><h2 id="thirteen-navbar-styles" tabindex="-1">Thirteen navbar styles <a class="header-anchor" href="#thirteen-navbar-styles" aria-label="Permalink to &quot;Thirteen navbar styles&quot;">​</a></h2><p>The navbar is a global option, independent of the skin:</p><p><code>Original capsule</code> · <code>Expanded pill</code> · <code>Side drawer</code> · <code>Glow cursor</code> · <code>Neon outline</code> · <code>Block cards</code> · <code>Gradient solid</code> · <code>Top indicator</code> · <code>Floating disc</code> · <code>Paper rule</code> · <code>White pill</code> · <code>Liquid pill</code> · <code>Nocturne neon</code></p><p>With the side-drawer style, each page reserves space on the left so content is never covered.</p><h2 id="customization-center" tabindex="-1">Customization center <a class="header-anchor" href="#customization-center" aria-label="Permalink to &quot;Customization center&quot;">​</a></h2><p>Every option is wired to a real setting and applies instantly, no restart required.</p><h3 id="wallpaper" tabindex="-1">Wallpaper <a class="header-anchor" href="#wallpaper" aria-label="Permalink to &quot;Wallpaper&quot;">​</a></h3><ul><li>Pick from the gallery, crop by dragging, zoom</li><li>Dim independently to keep foreground text readable</li><li>Turn the global background off entirely</li></ul><h3 id="cards" tabindex="-1">Cards <a class="header-anchor" href="#cards" aria-label="Permalink to &quot;Cards&quot;">​</a></h3><ul><li><strong>Artwork</strong>: the hero card, the four KPI cards and every module card can each carry its own image with independent opacity</li><li><strong>Colors</strong>: global color picking plus per-card overrides, and a one-tap rainbow</li><li><strong>Radius</strong>: one global corner radius</li></ul><h3 id="typography" tabindex="-1">Typography <a class="header-anchor" href="#typography" aria-label="Permalink to &quot;Typography&quot;">​</a></h3><p>Four presets — system, serif, monospace, rounded handwriting — or import your own font file.</p><h3 id="title-and-icons" tabindex="-1">Title and icons <a class="header-anchor" href="#title-and-icons" aria-label="Permalink to &quot;Title and icons&quot;">​</a></h3><ul><li>Custom home title text</li><li>Four fox launcher icons that follow the system theme</li><li>Icon shapes: rounded square, circle, squircle, rainbow gradient</li></ul><h3 id="light" tabindex="-1">Light <a class="header-anchor" href="#light" aria-label="Permalink to &quot;Light&quot;">​</a></h3><p>Immersive glow, liquid glass, rainbow icons and Monet color extraction — each can be toggled on its own.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/FoxSu/guide/installation.html">Install FoxSu</a></li><li><a href="/FoxSu/guide/app-profile.html">App Profile and permissions</a></li><li><a href="/FoxSu/guide/module.html">Module guide</a></li></ul>',25)])])}const g=t(i,[["render",n]]);export{p as __pageData,g as default};
